-- MAVIS Task Tracker 6.2.4
-- Поддержка задач без ответственного/дедлайна + фактическое время + импорт 85 задач в Бэклог.
-- Без удаления существующих данных. Повторный запуск не дублирует задачи этого импорта.

begin;

alter table public.projects add column if not exists backlog boolean not null default false;
alter table public.projects add column if not exists backlog_at timestamptz;
alter table public.tasks add column if not exists backlog boolean not null default false;
alter table public.tasks add column if not exists backlog_at timestamptz;

alter table public.tasks alter column owner drop not null;
alter table public.tasks alter column deadline drop not null;

alter table public.tasks add column if not exists actual_hours numeric(10,2);
alter table public.tasks add column if not exists completed_at timestamptz;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'tasks_actual_hours_positive'
      and conrelid = 'public.tasks'::regclass
  ) then
    alter table public.tasks
      add constraint tasks_actual_hours_positive
      check (actual_hours is null or actual_hours > 0);
  end if;
end $$;

create index if not exists tasks_actual_hours_idx on public.tasks(actual_hours);
create index if not exists tasks_completed_at_idx on public.tasks(completed_at);
create index if not exists tasks_backlog_idx on public.tasks(backlog);
create index if not exists projects_backlog_idx on public.projects(backlog);

drop table if exists pg_temp._mavis_strategy_projects;
create temporary table _mavis_strategy_projects (
  project_name text not null,
  project_goal text not null
) on commit drop;

insert into _mavis_strategy_projects(project_name, project_goal) values
  ('1. Клиентский контур', 'Сформировать систему работы с клиентской базой: рост LTV, повторных продаж, кросс-сейла, удержания и возврата клиентов.'),
  ('2. Команда', 'Снизить зависимость ключевых процессов от собственника: основные операционные решения принимаются руководителями в рамках согласованных полномочий и KPI.'),
  ('3. Эффективность сотрудников', 'Увеличить выручку на одного сотрудника без пропорционального увеличения штата.'),
  ('4. Перелидоз', 'Увеличить поток квалифицированных лидов выше внутренней мощности обработки и монетизировать избыток через партнеров/конкурентов.');

insert into public.projects (
  name, description, owner, deadline, status, color, backlog, backlog_at
)
select
  p.project_name,
  p.project_goal,
  'Без ответственного',
  null,
  'Ожидает',
  case p.project_name
    when '1. Клиентский контур' then '#D8E4FF'
    when '2. Команда' then '#D3F3E2'
    when '3. Эффективность сотрудников' then '#FFF0B8'
    when '4. Перелидоз' then '#FFD3E1'
    else '#E7D8FF'
  end,
  true,
  now()
from _mavis_strategy_projects p
where not exists (
  select 1 from public.projects existing
  where lower(trim(existing.name)) = lower(trim(p.project_name))
);

drop table if exists pg_temp._mavis_strategy_tasks;
create temporary table _mavis_strategy_tasks (
  source_row integer not null,
  project_name text not null,
  title text not null,
  owner text,
  deadline date,
  quarter text,
  kpi text,
  quarter_result text,
  source_deadline text,
  comment text
) on commit drop;

