insert into public.tasks (
  title, owner, deadline, period, status, priority, hours,
  start_time, end_time, block, result, comment, resource_url,
  project_id, stage_id, section_id, backlog, backlog_at,
  actual_hours, completed_at
)
select
  src.title,
  src.owner,
  src.deadline,
  'day',
  'Ожидает',
  'Средний',
  1,
  null,
  null,
  '',
  coalesce(src.kpi, ''),
  src.comment,
  '',
  p.id,
  null,
  null,
  true,
  now(),
  null,
  null
from _mavis_strategy_tasks src
join lateral (
  select id
  from public.projects p0
  where lower(trim(p0.name)) = lower(trim(src.project_name))
  order by p0.created_at asc
  limit 1
) p on true
where not exists (
  select 1
  from public.tasks existing
  where existing.project_id = p.id
    and existing.title = src.title
    and coalesce(existing.comment, '') like '%Импорт из файла «подготовка (1).xlsx»%'
    and coalesce(existing.comment, '') like '%строка ' || src.source_row::text || '.%'
);

notify pgrst, 'reload schema';

commit;

select
  (select count(*) from public.tasks
   where backlog = true and coalesce(comment, '') like '%Импорт из файла «подготовка (1).xlsx»%') as imported_backlog_tasks,
  (select count(*) from public.tasks
   where backlog = true and coalesce(comment, '') like '%Импорт из файла «подготовка (1).xlsx»%' and owner is not null) as with_owner,
  (select count(*) from public.tasks
   where backlog = true and coalesce(comment, '') like '%Импорт из файла «подготовка (1).xlsx»%' and deadline is not null) as with_deadline,
  (select count(*) from public.tasks
   where backlog = true and coalesce(comment, '') like '%Импорт из файла «подготовка (1).xlsx»%' and owner is null) as without_owner,
  (select count(*) from public.tasks
   where backlog = true and coalesce(comment, '') like '%Импорт из файла «подготовка (1).xlsx»%' and deadline is null) as without_deadline;
